package rita;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * LetterToSound — port of {@code js/src/rita_lts.js}. Builds phone lists for out-of-dictionary
 * words using the CMU6 letter-to-sound state machine (Black, Lenzo &amp; Pagel, 1998).
 *
 * <p>The rule table is loaded from the shared resource {@code rita/rita_lts.json} (generated by
 * {@code scripts/gen-lts.js} from the JS source) so it can never drift from the JS ground truth.
 */
class LetterToSound {

    /** A state in the LTS machine: either a {@link DecisionState} or a {@link FinalState}. */
    private interface State {
    }

    /** JS {@code DecisionState} — tests {@code chars[index] == c} and branches. */
    private static final class DecisionState implements State {
        final int index;
        final char c;
        final int qtrue;
        final int qfalse;

        DecisionState(int index, char c, int qtrue, int qfalse) {
            this.index = index;
            this.c = c;
            this.qtrue = qtrue;
            this.qfalse = qfalse;
        }

        int getNextState(char[] chars) {
            return (index < chars.length && chars[index] == c) ? qtrue : qfalse;
        }
    }

    /** JS {@code FinalState} — appends its phone list when reached. */
    private static final class FinalState implements State {
        final List<String> phoneList = new ArrayList<>();

        FinalState(String phones) {
            if (!"epsilon".equals(phones)) {
                int i = phones.indexOf('-');
                if (i != -1) {
                    phoneList.add(phones.substring(0, i));
                    phoneList.add(phones.substring(i + 1));
                } else {
                    phoneList.add(phones);
                }
            }
        }

        void append(List<String> array) {
            array.addAll(phoneList);
        }
    }

    private final Map<Character, Integer> letterIndex = new HashMap<>();
    private final char[] fvalBuff = new char[8];
    private int numStates = 0;
    private State[] stateMachine;
    private int stateMachineSize = 0;

    /** The rule table, loaded once per JVM from the shared resource. */
    private static List<String> rules;

    LetterToSound() {
        if (rules == null) {
            rules = loadRules();
        }
        for (String rule : rules) {
            parseAndAdd(rule);
        }
    }

    /** JS {@code createState(type)} — reads the remaining tokens for an S or P line. */
    private State createState(String type, String[] tokens) {
        if ("S".equals(type)) {
            int index = Integer.parseInt(tokens[1]);
            char c = tokens[2].charAt(0);
            int qtrue = Integer.parseInt(tokens[3]);
            int qfalse = Integer.parseInt(tokens[4]);
            return new DecisionState(index, c, qtrue, qfalse);
        } else if ("P".equals(type)) {
            return new FinalState(tokens[1]);
        }
        throw new RuntimeException("Unexpected type: " + type);
    }

    /** JS {@code parseAndAdd(line)}. */
    private void parseAndAdd(String line) {
        String[] tokens = line.split(" ");
        String type = tokens[0];
        if ("S".equals(type) || "P".equals(type)) {
            if (stateMachine == null) {
                stateMachine = new State[stateMachineSize];
            }
            stateMachine[numStates++] = createState(type, tokens);
        } else if ("I".equals(type)) {
            int index = Integer.parseInt(tokens[1]);
            if (index != numStates) {
                throw new RuntimeException("Bad index in file.");
            }
            letterIndex.put(tokens[2].charAt(0), index);
        } else if ("T".equals(type)) {
            stateMachineSize = Integer.parseInt(tokens[1]);
            stateMachine = new State[stateMachineSize];
        }
    }

    /** JS {@code buildPhones(word, opts)} — the phone list, or null when no phones are produced. */
    List<String> buildPhones(String word, Map<String, Object> opts) {
        if (word == null || word.isEmpty() || RiTa.isPunct(word)) {
            return null;
        }

        List<String> phoneList = new ArrayList<>();
        int windowSize = 4;

        boolean silent = RiTa.SILENT || RiTa.SILENCE_LTS || (opts != null && truthy(opts.get("silent")));

        word = word.toLowerCase();

        if (Util.isNum(word)) {
            if (word.matches("[0-9]+")) {
                String[] digits = word.length() > 1 ? word.split("") : new String[] {word};
                for (String digit : digits) {
                    String asWord = Util.Numbers.toWords.get(digit);
                    String phs = RiTa.lexicon.rawPhones(asWord, true);
                    phs = phs.replace("1", "").replace(" ", "-");
                    phoneList.addAll(List.of(phs.split("-")));
                }
                return phoneList;
            }
            // else fall through to the normal LTS path
        }

        // Create "000#word#000"
        String tmp = "000#" + word.trim() + "#000";
        char[] fullBuff = tmp.toCharArray();

        for (int pos = 0; pos < word.length(); pos++) {
            for (int i = 0; i < windowSize; i++) {
                fvalBuff[i] = charAt(fullBuff, pos + i);
                fvalBuff[i + windowSize] = charAt(fullBuff, i + pos + 1 + windowSize);
            }

            char c = word.charAt(pos);
            if (c == '\'') {
                continue;
            }
            Integer startIndex = letterIndex.get(c);
            if (startIndex == null) {
                if (!silent) {
                    System.err.println("[RiTa] Unable to generate LTS for '" + word + "', no index for '" + c + "'");
                }
                return null;
            }

            int stateIndex = startIndex;
            State currentState = getState(stateIndex);
            while (!(currentState instanceof FinalState)) {
                stateIndex = ((DecisionState) currentState).getNextState(fvalBuff);
                currentState = getState(stateIndex);
            }
            ((FinalState) currentState).append(phoneList);
        }
        return phoneList;
    }

    private State getState(int i) {
        return stateMachine[i];
    }

    /** JS {@code str.charAt(i)} on a char array — NUL for out-of-range, where Java would throw. */
    private static char charAt(char[] arr, int i) {
        return (i >= 0 && i < arr.length) ? arr[i] : '\0';
    }

    private static boolean truthy(Object o) {
        if (o == null) {
            return false;
        }
        if (o instanceof Boolean) {
            return (Boolean) o;
        }
        if (o instanceof Number) {
            return ((Number) o).doubleValue() != 0;
        }
        if (o instanceof String) {
            return !((String) o).isEmpty();
        }
        return true;
    }

    /** Loads the LTS rule table from the jar resource {@code rita/rita_lts.json}. */
    private static List<String> loadRules() {
        try (InputStream in = LetterToSound.class.getResourceAsStream("/rita/rita_lts.json")) {
            if (in == null) {
                throw new RuntimeException("Missing LTS resource: /rita/rita_lts.json");
            }
            try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8)) {
                List<?> raw = (List<?>) Json.parse(readAll(r));
                List<String> out = new ArrayList<>(raw.size());
                for (Object o : raw) {
                    out.add((String) o);
                }
                return out;
            }
        } catch (Exception e) {
            throw new RuntimeException("Failed to load rita_lts.json", e);
        }
    }

    private static String readAll(Reader r) throws java.io.IOException {
        StringBuilder sb = new StringBuilder(1 << 20);
        char[] buf = new char[8192];
        int n;
        while ((n = r.read(buf)) != -1) {
            sb.append(buf, 0, n);
        }
        return sb.toString();
    }
}
